import './styles.css';
import { useState } from 'react';

// Quiz questions about AI fundamentals
const questions = [
  {
    id: 1,
    question: "What does AI stand for?",
    options: [
      "Automated Internet",
      "Artificial Intelligence",
      "Advanced Integration",
      "Automatic Information"
    ],
    correct: 1,
    explanation: "AI stands for Artificial Intelligence - technology that enables machines to perform tasks that normally require human thinking."
  },
  {
    id: 2,
    question: "Which type of AI exists today?",
    options: [
      "Superintelligent AI",
      "General AI (Strong AI)",
      "Narrow AI (Weak AI)",
      "All of the above"
    ],
    correct: 2,
    explanation: "Only Narrow AI exists today. It excels at specific tasks but can't generalize like humans. General AI and Superintelligent AI remain theoretical."
  },
  {
    id: 3,
    question: "When was the term 'Artificial Intelligence' officially coined?",
    options: [
      "1936",
      "1956",
      "1976",
      "1996"
    ],
    correct: 1,
    explanation: "The term was coined at the Dartmouth Conference in 1956, organized by John McCarthy. This event is considered the birth of AI as a field."
  },
  {
    id: 4,
    question: "Which is an example of AI you might use daily?",
    options: [
      "A light switch",
      "Email spam filter",
      "A regular calculator",
      "A paper notebook"
    ],
    correct: 1,
    explanation: "Spam filters use AI to learn patterns and identify unwanted emails. They improve over time by learning from examples - a key characteristic of AI."
  },
  {
    id: 5,
    question: "What is 'Machine Learning'?",
    options: [
      "Robots learning to walk",
      "Computers learning from data instead of explicit rules",
      "Humans learning about machines",
      "Automatic software updates"
    ],
    correct: 1,
    explanation: "Machine Learning is an approach where computers learn patterns from data rather than following explicit programming rules. It's what makes modern AI so powerful."
  },
  {
    id: 6,
    question: "What was the 'AI Winter'?",
    options: [
      "A season when AI works best",
      "A period of reduced funding and interest in AI research",
      "A type of AI that handles cold weather",
      "An AI-powered weather app"
    ],
    correct: 1,
    explanation: "AI Winters were periods when funding and interest in AI research declined due to unfulfilled promises. There were two major AI Winters: 1974-1980 and the late 1980s."
  },
  {
    id: 7,
    question: "Which statement about AI is TRUE?",
    options: [
      "AI can think and feel like humans",
      "AI is always correct and never makes mistakes",
      "AI learns from data and can recognize patterns",
      "AI will soon replace all human jobs"
    ],
    correct: 2,
    explanation: "AI systems learn from data and excel at finding patterns. However, they don't truly 'think' or have feelings, they make mistakes, and they're tools that assist (not replace) humans."
  },
  {
    id: 8,
    question: "General AI (Strong AI) would be able to:",
    options: [
      "Only play chess",
      "Only recognize faces",
      "Perform any intellectual task a human can",
      "Only answer questions about one topic"
    ],
    correct: 2,
    explanation: "General AI would match human-level intelligence across ALL domains - learning any task, transferring knowledge between areas, and understanding context. It doesn't exist yet."
  }
];

function QuizCard({ question, selectedAnswer, onSelect, showResult }: {
  question: typeof questions[0];
  selectedAnswer: number | null;
  onSelect: (index: number) => void;
  showResult: boolean;
}) {
  return (
    <div className="quiz-card">
      <h3 className="question">{question.question}</h3>
      <div className="options">
        {question.options.map((option, index) => {
          let className = 'option';
          if (showResult) {
            if (index === question.correct) {
              className += ' correct';
            } else if (index === selectedAnswer && index !== question.correct) {
              className += ' incorrect';
            }
          } else if (index === selectedAnswer) {
            className += ' selected';
          }

          return (
            <button
              key={index}
              className={className}
              onClick={() => !showResult && onSelect(index)}
              disabled={showResult}
            >
              <span className="option-letter">{String.fromCharCode(65 + index)}</span>
              {option}
            </button>
          );
        })}
      </div>
      {showResult && (
        <div className={`explanation ${selectedAnswer === question.correct ? 'correct' : 'incorrect'}`}>
          <p><strong>{selectedAnswer === question.correct ? 'Correct!' : 'Not quite!'}</strong></p>
          <p>{question.explanation}</p>
        </div>
      )}
    </div>
  );
}

function Results({ score, total, onRestart }: {
  score: number;
  total: number;
  onRestart: () => void;
}) {
  const percentage = Math.round((score / total) * 100);
  let message = '';
  let emoji = '';

  if (percentage >= 90) {
    message = 'AI Expert!';
    emoji = '🏆';
  } else if (percentage >= 70) {
    message = 'Great job!';
    emoji = '🌟';
  } else if (percentage >= 50) {
    message = 'Good start!';
    emoji = '👍';
  } else {
    message = 'Keep learning!';
    emoji = '📚';
  }

  return (
    <div className="results">
      <div className="results-emoji">{emoji}</div>
      <h2>{message}</h2>
      <p className="score-text">You got <strong>{score}</strong> out of <strong>{total}</strong> correct</p>
      <div className="score-bar">
        <div className="score-fill" style={{ width: `${percentage}%` }} />
      </div>
      <p className="percentage">{percentage}%</p>
      <button className="restart-btn" onClick={onRestart}>
        Try Again
      </button>
    </div>
  );
}

export default function App() {
  const [currentQuestion, setCurrentQuestion] = useState(0);
  const [answers, setAnswers] = useState<(number | null)[]>(new Array(questions.length).fill(null));
  const [submitted, setSubmitted] = useState<boolean[]>(new Array(questions.length).fill(false));
  const [quizComplete, setQuizComplete] = useState(false);

  const handleSelect = (index: number) => {
    const newAnswers = [...answers];
    newAnswers[currentQuestion] = index;
    setAnswers(newAnswers);
  };

  const handleSubmit = () => {
    const newSubmitted = [...submitted];
    newSubmitted[currentQuestion] = true;
    setSubmitted(newSubmitted);
  };

  const handlePrevious = () => {
    if (currentQuestion > 0) {
      setCurrentQuestion(currentQuestion - 1);
    }
  };

  const handleNext = () => {
    if (currentQuestion < questions.length - 1) {
      setCurrentQuestion(currentQuestion + 1);
    }
  };

  const handleFinish = () => {
    setQuizComplete(true);
  };

  const handleRestart = () => {
    setCurrentQuestion(0);
    setAnswers(new Array(questions.length).fill(null));
    setSubmitted(new Array(questions.length).fill(false));
    setQuizComplete(false);
  };

  const score = answers.reduce((acc, answer, index) => {
    return acc + (answer === questions[index].correct ? 1 : 0);
  }, 0);

  const allSubmitted = submitted.every(s => s);
  const isCurrentSubmitted = submitted[currentQuestion];
  const isLastQuestion = currentQuestion === questions.length - 1;
  const isFirstQuestion = currentQuestion === 0;

  if (quizComplete) {
    return (
      <div className="app">
        <Results score={score} total={questions.length} onRestart={handleRestart} />
      </div>
    );
  }

  return (
    <div className="app">
      <div className="header">
        <h1>AI Concepts Quiz</h1>
        <p className="subtitle">Test your understanding of artificial intelligence</p>
      </div>

      <div className="progress">
        <div className="progress-bar">
          <div 
            className="progress-fill" 
            style={{ width: `${((currentQuestion + 1) / questions.length) * 100}%` }} 
          />
        </div>
        <span className="progress-text">
          Question {currentQuestion + 1} of {questions.length}
        </span>
      </div>

      <QuizCard
        question={questions[currentQuestion]}
        selectedAnswer={answers[currentQuestion]}
        onSelect={handleSelect}
        showResult={isCurrentSubmitted}
      />

      <div className="nav-buttons">
        <button
          className="nav-btn prev-btn"
          onClick={handlePrevious}
          disabled={isFirstQuestion}
        >
          Previous
        </button>

        {!isCurrentSubmitted ? (
          <button
            className="nav-btn submit-btn"
            onClick={handleSubmit}
            disabled={answers[currentQuestion] === null}
          >
            Check Answer
          </button>
        ) : isLastQuestion ? (
          <button
            className="nav-btn finish-btn"
            onClick={handleFinish}
            disabled={!allSubmitted}
          >
            {allSubmitted ? 'See Results' : 'Answer All Questions'}
          </button>
        ) : (
          <button
            className="nav-btn next-btn"
            onClick={handleNext}
          >
            Next
          </button>
        )}
      </div>

      {!allSubmitted && (
        <p className="hint-text">
          Answer all questions to see your final score
        </p>
      )}
    </div>
  );
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: linear-gradient(135deg, #6366f1 0%, #8b5cf6 100%);
  min-height: 100vh;
  padding: 2rem 1rem;
}

.app {
  max-width: 700px;
  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 2rem;
}

h1 {
  color: white;
  font-size: 2rem;
  margin-bottom: 0.5rem;
}

.subtitle {
  color: rgba(255, 255, 255, 0.8);
  font-size: 1rem;
}

.progress {
  margin-bottom: 1.5rem;
}

.progress-bar {
  height: 8px;
  background: rgba(255, 255, 255, 0.3);
  border-radius: 4px;
  overflow: hidden;
  margin-bottom: 0.5rem;
}

.progress-fill {
  height: 100%;
  background: white;
  border-radius: 4px;
  transition: width 0.3s ease;
}

.progress-text {
  color: rgba(255, 255, 255, 0.9);
  font-size: 0.875rem;
}

.quiz-card {
  background: white;
  border-radius: 1rem;
  padding: 2rem;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
  margin-bottom: 1.5rem;
}

.question {
  font-size: 1.25rem;
  color: #1f2937;
  margin-bottom: 1.5rem;
  line-height: 1.4;
}

.options {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.option {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 1rem 1.25rem;
  background: #f9fafb;
  border: 2px solid #e5e7eb;
  border-radius: 0.75rem;
  cursor: pointer;
  transition: all 0.2s;
  text-align: left;
  font-size: 1rem;
  color: #374151;
}

.option:hover:not(:disabled) {
  border-color: #6366f1;
  background: #f5f3ff;
}

.option.selected {
  border-color: #6366f1;
  background: #eef2ff;
}

.option.correct {
  border-color: #10b981;
  background: #d1fae5;
  color: #065f46;
}

.option.incorrect {
  border-color: #ef4444;
  background: #fee2e2;
  color: #991b1b;
}

.option:disabled {
  cursor: default;
}

.option-letter {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  background: #e5e7eb;
  border-radius: 50%;
  font-weight: 600;
  font-size: 0.875rem;
  color: #6b7280;
  flex-shrink: 0;
}

.option.selected .option-letter {
  background: #6366f1;
  color: white;
}

.option.correct .option-letter {
  background: #10b981;
  color: white;
}

.option.incorrect .option-letter {
  background: #ef4444;
  color: white;
}

.explanation {
  margin-top: 1.5rem;
  padding: 1rem;
  border-radius: 0.75rem;
  font-size: 0.95rem;
  line-height: 1.5;
}

.explanation.correct {
  background: #d1fae5;
  color: #065f46;
}

.explanation.incorrect {
  background: #fef3c7;
  color: #92400e;
}

.explanation p:first-child {
  margin-bottom: 0.5rem;
}

/* Navigation Buttons */
.nav-buttons {
  display: flex;
  gap: 1rem;
}

.nav-btn {
  flex: 1;
  padding: 1rem;
  border: none;
  border-radius: 0.75rem;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
}

.nav-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.prev-btn {
  background: rgba(255, 255, 255, 0.2);
  color: white;
}

.prev-btn:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.3);
}

.next-btn, .submit-btn {
  background: white;
  color: #6366f1;
}

.next-btn:hover:not(:disabled), .submit-btn:hover:not(:disabled) {
  background: #f5f3ff;
  transform: translateY(-2px);
}

.finish-btn {
  background: linear-gradient(135deg, #10b981, #059669);
  color: white;
}

.finish-btn:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 4px 15px rgba(16, 185, 129, 0.4);
}

.hint-text {
  text-align: center;
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.875rem;
  margin-top: 1rem;
}

/* Results Screen */
.results {
  background: white;
  border-radius: 1rem;
  padding: 3rem 2rem;
  text-align: center;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
}

.results-emoji {
  font-size: 4rem;
  margin-bottom: 1rem;
}

.results h2 {
  color: #1f2937;
  font-size: 1.75rem;
  margin-bottom: 1rem;
}

.score-text {
  color: #6b7280;
  font-size: 1.125rem;
  margin-bottom: 1.5rem;
}

.score-text strong {
  color: #6366f1;
}

.score-bar {
  height: 12px;
  background: #e5e7eb;
  border-radius: 6px;
  overflow: hidden;
  margin-bottom: 0.5rem;
}

.score-fill {
  height: 100%;
  background: linear-gradient(90deg, #6366f1, #8b5cf6);
  border-radius: 6px;
  transition: width 0.5s ease;
}

.percentage {
  color: #6366f1;
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 2rem;
}

.restart-btn {
  padding: 1rem 2rem;
  background: linear-gradient(135deg, #6366f1, #8b5cf6);
  color: white;
  border: none;
  border-radius: 0.75rem;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
}

.restart-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 15px rgba(99, 102, 241, 0.4);
}
